/**
 * Every city over 100k inhabitants (GeoNames), each with a notable central
 * landmark (Wikidata) to land on. The data lives in worldCitiesData.ts,
 * generated by tools/worldCities/generate.mjs, and is loaded lazily so it
 * stays out of the main bundle.
 */
export interface City {
  name: string;
  /** Landmark the coordinates point at, or '' when they are the city center. */
  landmark: string;
  lat: number;
  lng: number;
  population: number;
}

interface CityTable {
  cities: City[];
  /** Running sum of pick weights, for binary-search weighted picking. */
  cumulative: Float64Array;
}

let tablePromise: Promise<CityTable> | null = null;

function loadTable(): Promise<CityTable> {
  tablePromise ??= import('./worldCitiesData').then(({ default: rows }) => {
    const cities = rows.map(([name, landmark, lat, lng, population]) => ({ name, landmark, lat, lng, population }));
    // sqrt(population): big cities still come up more often, but Tokyo is
    // ~12x as likely as a 100k town instead of ~140x.
    const cumulative = new Float64Array(cities.length);
    let sum = 0;
    cities.forEach((c, i) => (cumulative[i] = sum += Math.sqrt(c.population)));
    return { cities, cumulative };
  });
  return tablePromise;
}

/** Random city, weighted by sqrt(population). Optionally rejects cities for which `reject` is true (a few tries). */
export async function pickRandomCity(reject?: (city: City) => boolean): Promise<City> {
  const { cities, cumulative } = await loadTable();
  const pick = () => {
    const r = Math.random() * cumulative[cumulative.length - 1];
    let lo = 0;
    let hi = cumulative.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (cumulative[mid] < r) lo = mid + 1;
      else hi = mid;
    }
    return cities[lo];
  };
  let city = pick();
  for (let i = 0; i < 8 && reject?.(city); i++) city = pick();
  return city;
}

/** City by name (case-insensitive); the most populous one when the name is ambiguous. */
export async function findCity(name: string): Promise<City | undefined> {
  const { cities } = await loadTable();
  const lower = name.toLowerCase();
  return cities.find(c => c.name.toLowerCase() === lower); // rows are sorted by population
}

export function describeCity(city: City): string {
  return city.landmark ? `${city.landmark}, ${city.name}` : city.name;
}

/** Lowercase without diacritics (and ’ as '), so "sao" finds "São Paulo". */
export function normalizeName(s: string): string {
  return s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’`]/g, "'").toLowerCase().trim();
}

let searchIndex: Promise<{ cities: City[]; names: string[] }> | null = null;

/**
 * Cities matching a typed query, for autocomplete: names that start with it first, then names with a word starting
 * with it, then names containing it, each in population order. Case and diacritics are ignored.
 */
export async function searchCities(query: string, limit: number = 8): Promise<City[]> {
  const q = normalizeName(query);
  if (!q) return [];
  searchIndex ??= loadTable().then(({ cities }) => ({ cities, names: cities.map(c => normalizeName(c.name)) }));
  const { cities, names } = await searchIndex;
  const prefix: City[] = [];
  const word: City[] = [];
  const contains: City[] = [];
  for (let i = 0; i < cities.length && prefix.length < limit; i++) {
    const at = names[i].indexOf(q);
    if (at < 0) continue;
    if (at === 0) prefix.push(cities[i]);
    else if (/[\s\-'(]/.test(names[i][at - 1])) word.push(cities[i]);
    else contains.push(cities[i]);
  }
  return [...prefix, ...word, ...contains].slice(0, limit);
}
